/* engine.js — zoom-nest engine. Reads THEME + STORY from story.js. Normally you do not edit this file.
   Idea: scene i+1 is drawn INSIDE a screen/window of scene i, so one camera move (scale + translate of a single world) goes
   from one scene into the next. The nested layers are real DOM children, so each frame is just one CSS transform.
   Motion's scroll() maps page scroll to a position f in [0, stops-1]; a dwell plateau at every stop leaves time to read. */
const { animate, scroll } = Motion;
const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
const rtl = THEME.dir === 'rtl';
const UI = THEME.ui;

const $ = (s, r = document) => r.querySelector(s);
const $$ = (s, r = document) => [...r.querySelectorAll(s)];
const asList = x => (Array.isArray(x) ? x : [x]);
function el(tag, attrs = {}, ...kids) {
  const e = document.createElement(tag);
  for (const k in attrs) { if (k === 'class') e.className = attrs[k]; else e.setAttribute(k, attrs[k]); }
  kids.flat().forEach(c => e.append(c));
  return e;
}
function rich(text) {   // [text](url) in copy becomes a link that opens in a new tab
  const out = []; const re = /\[([^\]]+)\]\(([^)]+)\)/g; let last = 0, m;
  while ((m = re.exec(text))) {
    if (m.index > last) out.push(document.createTextNode(text.slice(last, m.index)));
    out.push(el('a', { class: 'inlink', href: m[2], target: '_blank', rel: 'noopener noreferrer' }, m[1]));
    last = re.lastIndex;
  }
  if (last < text.length) out.push(document.createTextNode(text.slice(last)));
  return out;
}
const link = (label, url) => url
  ? el('a', { class: 'chip', href: url, target: '_blank', rel: 'noopener noreferrer' }, label)
  : el('span', { class: 'chip tbd' }, label + ' · link TBD');   // never invent a link

/* ---------- theme ---------- */
{
  const root = document.documentElement;
  root.lang = THEME.lang || 'en'; root.dir = THEME.dir || 'ltr'; root.classList.toggle('rtl', rtl);
  document.title = THEME.title;
  Object.entries(THEME.tokens || {}).forEach(([k, v]) => root.style.setProperty(k, v));
  if (THEME.fonts) {
    if (THEME.fonts.serif) root.style.setProperty('--serif', THEME.fonts.serif);
    if (THEME.fonts.sans) root.style.setProperty('--sans', THEME.fonts.sans);
    if (THEME.fonts.href) document.head.append(el('link', { rel: 'stylesheet', href: THEME.fonts.href }));
  }
}

/* ---------- geometry: each layer's rectangle in the outermost layer's coordinates (fractions 0..1) ---------- */
const LAYERS = STORY.layers, N = LAYERS.length;
const R = [[0, 0, 1, 1]];
for (let i = 1; i < N; i++) { const p = R[i - 1], f = LAYERS[i].frame; R.push([p[0] + f[0] * p[2], p[1] + f[1] * p[3], f[2] * p[2], f[3] * p[3]]); }
const ORDER = THEME.direction === 'out' ? [...Array(N).keys()].reverse() : [...Array(N).keys()];   // stop k shows layer ORDER[k]

/* ---------- DOM: nested layers ---------- */
const world = $('#world');
function mount(i, parent) {
  const L = LAYERS[i];
  const box = el('div', { class: 'layer' + (i ? ' framed' : ''), 'data-i': String(i) });
  if (i) { const [x, y, w, h] = L.frame; box.style.cssText = `left:${x * 100}%;top:${y * 100}%;width:${w * 100}%;height:${h * 100}%`; } else box.style.cssText = 'inset:0';
  box.append(el('img', { src: L.image, alt: L.alt || '', draggable: 'false' }));
  parent.append(box);
  if (i + 1 < N) mount(i + 1, box);
}
mount(0, world);

/* ---------- captions + dots ---------- */
const caps = ORDER.map((li, k) => {
  const L = LAYERS[li];
  const hero = L.hero;
  const card = el('div', { class: 'card' },
    ...(hero ? [] : [el('div', { class: 'label' }, `${UI.step} ${k + 1}`)]),
    el(hero ? 'h1' : 'h2', {}, L.title),
    ...asList(L.body || []).map(t => el('p', {}, ...rich(t))),
    ...(L.refs ? [el('div', { class: 'refs' }, ...L.refs.map(([l, u]) => link(l, u)))] : []));
  const cap = el('section', { class: 'cap ' + (L.side || 'left') + (hero ? ' hero center' : ''), 'aria-label': L.title }, card);
  $('#caps').append(cap);
  return cap;
});
ORDER.forEach((li, k) => {
  const b = el('button', { type: 'button', 'data-k': String(k), 'aria-label': LAYERS[li].nav || LAYERS[li].title, 'aria-current': String(k === 0) }, el('span', {}, LAYERS[li].nav || LAYERS[li].title));
  b.onclick = () => goStop(k);
  $('#dots').append(b);
});
$('#hint').textContent = UI.scrollHint;

/* ---------- the camera ---------- */
const track = $('#track');
track.style.height = (N * 100) + 'vh';
function geom() { const vw = innerWidth, vh = innerHeight, W = Math.max(vw, vh * 1.5); return { vw, vh, W, H: W * 2 / 3 }; }
/* view rectangle at position f: log-interpolated width (constant zoom speed), centre moves linearly with the zoomed fraction */
function view(f) {
  const i = Math.min(N - 1, Math.floor(f)), j = Math.min(N - 1, i + 1), t = f - i;
  const A = R[ORDER[i]], B = R[ORDER[j]];
  const w = Math.exp(Math.log(A[2]) * (1 - t) + Math.log(B[2]) * t);
  const u = A[2] === B[2] ? t : (A[2] - w) / (A[2] - B[2]);
  const cx = (A[0] + A[2] / 2) * (1 - u) + (B[0] + B[2] / 2) * u, cy = (A[1] + A[3] / 2) * (1 - u) + (B[1] + B[3] / 2) * u;
  return { cx, cy, w };
}
let curF = 0;
function paint(f) {
  const { vw, vh, W, H } = geom(), v = view(f), s = 1 / v.w;
  world.style.width = W + 'px'; world.style.height = H + 'px';
  world.style.transform = `translate(${vw / 2 - s * v.cx * W}px,${vh / 2 - s * v.cy * H}px) scale(${s})`;
  caps.forEach((c, k) => { const d = Math.abs(f - k); c.style.opacity = Math.max(0, Math.min(1, (0.5 - d) / 0.22)); c.style.pointerEvents = d < 0.3 ? 'auto' : 'none'; });
  const cur = Math.round(f);
  $$('#dots button').forEach(b => b.setAttribute('aria-current', String(+b.dataset.k === cur)));
  $('#hint').style.opacity = f < 0.05 ? 1 : 0;
  curF = f;
}
const smooth = x => x * x * (3 - 2 * x);
/* dwell: hold ~30% of the scroll at every stop, move in the middle 40% */
function fromProgress(p) {
  const raw = p * (N - 1), i = Math.min(N - 1, Math.floor(raw)), frac = raw - i;
  const f = i + smooth(Math.max(0, Math.min(1, (frac - 0.3) / 0.4)));
  return reduce ? Math.round(f) : f;
}
scroll(p => paint(fromProgress(p)));
scroll(animate('#bar', { scaleX: [0, 1] }, { ease: 'linear' }));
addEventListener('resize', () => paint(curF));
paint(0);

/* ---------- navigation ---------- */
function goStop(k) {
  const max = document.documentElement.scrollHeight - innerHeight;
  scrollTo({ top: N > 1 ? (k / (N - 1)) * max : 0, behavior: reduce ? 'auto' : 'smooth' });
}
let nav = { i: null, t: 0 };
addEventListener('keydown', e => {
  if (e.metaKey || e.ctrlKey || e.altKey || e.target.closest?.('input,textarea')) return;
  const dir = ['ArrowDown', 'PageDown', 'j', ' '].includes(e.key) ? 1 : ['ArrowUp', 'PageUp', 'k'].includes(e.key) ? -1 : 0;
  if (!dir) return;
  e.preventDefault();
  const base = nav.i !== null && Date.now() - nav.t < 1600 ? nav.i : Math.round(curF);
  const n = Math.max(0, Math.min(N - 1, base + dir));
  if (n === base) return;
  nav = { i: n, t: Date.now() };
  goStop(n);
});
